examples.template:
Box {
    MonarchButton(
        text = {{label}},
        onClick = { expanded = true },
        modifier = Modifier.semantics {
            stateDescription = if (expanded) "Expanded" else "Collapsed"
        },
        trailingIcon = {
            MonarchIcon(
                if (expanded) SampleIcons.ChevronUp else SampleIcons.ChevronDown,
                contentDescription = null,
                size = MonarchIconSize.Sm,
            )
        },
    )
    MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
        MonarchMenuItem(
            text = {{items.0.label}},
            onClick = { expanded = false },
            leadingIcon = { MonarchIcon(SampleIcons.Pencil, contentDescription = null, size = MonarchIconSize.Sm) },
        )
        MonarchMenuItem(text = {{items.1.label}}, onClick = { expanded = false }, shortcut = {{items.1.shortcut}})
        MonarchMenuDivider()
        MonarchMenuItem(
            text = {{items.2.label}},
            onClick = { expanded = false },
            destructive = true,
            leadingIcon = { MonarchIcon(SampleIcons.Trash, contentDescription = null, size = MonarchIconSize.Sm) },
        )
    }
}

